#!/usr/bin/env bash
# Universal Ubuntu VPS bootstrap for jq (v14.0)
# Designed for fresh installs and safe recovery on small Ubuntu cloud VMs.
#
# Design:
#   * Bash-only bootstrap. Never enters an interactive jq shell during setup.
#   * Checkpointed and idempotent: successful steps are marked under /var/lib/jq-bootstrap.
#   * Every step verifies its result before being considered complete.
#   * A final audit retries failed categories once before returning failure.
#   * SSH hardening is deliberately the LAST destructive networking step.
#
# Run from the same directory as .env:
#   chmod +x bootstrap.sh
#   ./bootstrap.sh
#
# The script elevates itself with sudo. Do not run it through `sh`.

set -Eeuo pipefail
IFS=$'\n\t'
umask 022

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"
ENV_FILE="${BOOTSTRAP_ENV_FILE:-$SCRIPT_DIR/.env}"

# Bash always has a HOSTNAME shell variable. Record whether the .env explicitly
# defines HOSTNAME so we can distinguish user configuration from Bash's automatic value.
ENV_HAS_HOSTNAME=0
if [[ -f "$ENV_FILE" ]] && grep -Eq '^[[:space:]]*(export[[:space:]]+)?HOSTNAME=' "$ENV_FILE"; then
  ENV_HAS_HOSTNAME=1
fi

# Preserve the real invoking user before sudo/root. This is provider-agnostic:
# GCE usernames, ubuntu, opc, ec2-user, custom users, etc. are all supported.
if (( EUID != 0 )); then
  invoker="${BOOTSTRAP_INVOKER:-${USER:-$(id -un)}}"
  exec sudo env \
    BOOTSTRAP_INVOKER="$invoker" \
    BOOTSTRAP_ENV_FILE="$ENV_FILE" \
    /usr/bin/env bash "$0" "$@"
fi

if [[ ! -f "$ENV_FILE" ]]; then
  echo "ERROR: Missing environment file: $ENV_FILE" >&2
  exit 2
fi

# shellcheck disable=SC1090
set -a
source "$ENV_FILE"
set +a
chmod 600 "$ENV_FILE" 2>/dev/null || true

# Everything operational is configurable from .env. Defaults are only sane
# fallbacks, never hidden per-provider assumptions.
TARGET_USER="${TARGET_USER:-jq}"
TARGET_HOME="${TARGET_HOME:-/home/$TARGET_USER}"
SSH_PORT="${SSH_PORT:-6722}"
SWAP_FILE="${SWAP_FILE:-/swapfile}"
# Happy Edition installer/update sources. panel.luce.moe is the current primary
# mirror. aa.maxcdn.top is retained strictly as a fallback for bootstrap/upgrades.
# AAPANEL_UPGRADE_URL is accepted as a backward-compatible override for older .env files.
AAPANEL_URL_PRIMARY="${AAPANEL_URL_PRIMARY:-https://panel.luce.moe/install/install_7.0_en.sh}"
AAPANEL_URL_FALLBACK="${AAPANEL_URL_FALLBACK:-https://aa.maxcdn.top/install/install_7.0_en.sh}"
AAPANEL_UPGRADE_URL_PRIMARY="${AAPANEL_UPGRADE_URL_PRIMARY:-${AAPANEL_UPGRADE_URL:-https://panel.luce.moe/install/update_7.x_en.sh}}"
AAPANEL_UPGRADE_URL_FALLBACK="${AAPANEL_UPGRADE_URL_FALLBACK:-https://aa.maxcdn.top/install/update_7.x_en.sh}"
AAPANEL_EXPECTED_VERSION="${AAPANEL_EXPECTED_VERSION:-8.0.7}"
# Exact per-panel certificates avoid Let's Encrypt duplicate-set limits when
# several servers share the same root zone. Ordinary websites can still use
# wildcard certificates through aaPanel's normal SSL UI.
AAPANEL_PANEL_CERT_MODE="${AAPANEL_PANEL_CERT_MODE:-exact}"
AAPANEL_DNS_PROPAGATION_SECONDS="${AAPANEL_DNS_PROPAGATION_SECONDS:-60}"
AAPANEL_DOWNLOAD_CONNECT_TIMEOUT="${AAPANEL_DOWNLOAD_CONNECT_TIMEOUT:-12}"
AAPANEL_DOWNLOAD_MAX_TIME="${AAPANEL_DOWNLOAD_MAX_TIME:-60}"
AAPANEL_ROOT="${AAPANEL_ROOT:-/www}"
AAPANEL_PANEL_DIR="${AAPANEL_PANEL_DIR:-$AAPANEL_ROOT/server/panel}"
AAPANEL_NGINX_DIR="${AAPANEL_NGINX_DIR:-$AAPANEL_ROOT/server/nginx}"
AAPANEL_WWWROOT="${AAPANEL_WWWROOT:-$AAPANEL_ROOT/wwwroot}"
AAPANEL_NGINX_FALLBACK_VERSION="${AAPANEL_NGINX_FALLBACK_VERSION:-1.30}"
# Optional forced aaPanel Nginx branch (for example 1.30). This is useful when
# aaPanel's App Store metadata contains a panel/plugin version that is newer
# than the actual Nginx branch and would otherwise be mistaken for Nginx.
AAPANEL_NGINX_VERSION_OVERRIDE="${AAPANEL_NGINX_VERSION_OVERRIDE:-}"
# Nginx install watchdog. aaPanel source builds can be slow on tiny VMs, so
# output silence alone is not treated as failure while compiler processes are busy.
AAPANEL_NGINX_CHECK_INTERVAL="${AAPANEL_NGINX_CHECK_INTERVAL:-15}"
AAPANEL_NGINX_STALL_SECONDS="${AAPANEL_NGINX_STALL_SECONDS:-240}"
# 0 = no absolute wall-clock kill. Progress/idle detection is safer for tiny VMs.
# Backward-compatible old env values (for example 2700) are treated as a soft
# ceiling while the installer is demonstrably active.
AAPANEL_NGINX_HARD_TIMEOUT="${AAPANEL_NGINX_HARD_TIMEOUT:-0}"
# aaPanel install_soft.sh uses method 1 for speed/prebuilt installation and
# method 0 for compilation. Prefer speed install and compile only as fallback.
AAPANEL_NGINX_QUICK_FIRST="${AAPANEL_NGINX_QUICK_FIRST:-1}"
AAPANEL_NGINX_COMPILE_FALLBACK="${AAPANEL_NGINX_COMPILE_FALLBACK:-1}"
# Legacy v10 knob retained so old .env files remain harmlessly parseable.
AAPANEL_NGINX_TYPE0_FALLBACK="${AAPANEL_NGINX_TYPE0_FALLBACK:-0}"
AAPANEL_PORT="${AAPANEL_PORT:-8886}"
AAPANEL_USER="${AAPANEL_USER:-p5n}"
CLOUDFLARE_ALIAS="${CLOUDFLARE_ALIAS:-global}"
PORTSEY_REPO="${PORTSEY_REPO:-https://github.com/joeyqleq/Portsey}"
NANORC_REPO="${NANORC_REPO:-https://github.com/scopatz/nanorc}"
# Curated terminal theme pair. random/auto selects one complete Nano + Powerlevel10k combo per bootstrap run.
TERMINAL_THEME="${TERMINAL_THEME:-random}"
BREW_PREFIX="${BREW_PREFIX:-/home/linuxbrew/.linuxbrew}"
BREW_BIN="${BREW_BIN:-$BREW_PREFIX/bin/brew}"
STATE_DIR="${STATE_DIR:-/var/lib/jq-bootstrap}"
LOG_FILE="${LOG_FILE:-/var/log/jq-bootstrap.log}"
AUTO_ENTER_TARGET_SHELL="${AUTO_ENTER_TARGET_SHELL:-1}"
STEP_WATCHDOG_SECONDS="${STEP_WATCHDOG_SECONDS:-45}"
HOMEBREW_AUTO_YES="${HOMEBREW_AUTO_YES:-1}"
Z4H_UPSTREAM_URL="${Z4H_UPSTREAM_URL:-https://raw.githubusercontent.com/romkatv/zsh4humans/v5}"
Z4H_CORE_TIMEOUT="${Z4H_CORE_TIMEOUT:-180}"
Z4H_FINALIZE_TIMEOUT="${Z4H_FINALIZE_TIMEOUT:-240}"
Z4H_NET_CONNECT_TIMEOUT="${Z4H_NET_CONNECT_TIMEOUT:-15}"
Z4H_NET_MAX_TIME="${Z4H_NET_MAX_TIME:-120}"
Z4H_KEYBOARD="${Z4H_KEYBOARD:-pc}"
Z4H_START_TMUX="${Z4H_START_TMUX:-no}"
Z4H_DIRENV="${Z4H_DIRENV:-yes}"

# --- aaPanel visual branding -------------------------------------------------
AAPANEL_BRANDING_ENABLED="${AAPANEL_BRANDING_ENABLED:-1}"
AAPANEL_BRANDING_TITLE="${AAPANEL_BRANDING_TITLE:-auto}"
AAPANEL_BRANDING_SUBTITLE="${AAPANEL_BRANDING_SUBTITLE:-SERVER DASHBOARD}"

# --- Optional AI inference stack ------------------------------------------------
# AI_INFERENCE_MODE: ask (interactive fresh installs), 1/yes/on, or 0/no/off.
# Recovery reuses the persisted choice under STATE_DIR so it never silently
# changes the role of a machine.
AI_INFERENCE_MODE="${AI_INFERENCE_MODE:-ask}"
OXRC_GEMINI_API_KEY="${OXRC_GEMINI_API_KEY:-}"
OPENWEBUI_SUBDOMAIN="${OPENWEBUI_SUBDOMAIN:-auto}"
OPENWEBUI_PORT="${OPENWEBUI_PORT:-3000}"
OLLAMA_PORT="${OLLAMA_PORT:-11434}"
AI_COMPOSE_NAME="${AI_COMPOSE_NAME:-openwebui-ollama}"
AI_PRIMARY_MODEL="${AI_PRIMARY_MODEL:-auto}"
AI_REASONING_MODEL="${AI_REASONING_MODEL:-gpt-oss:20b}"
AI_PULL_REASONING_MODEL="${AI_PULL_REASONING_MODEL:-1}"
AI_DECISION_MODEL="${AI_DECISION_MODEL:-tev1:0.8b}"
AI_PULL_DECISION_MODEL="${AI_PULL_DECISION_MODEL:-1}"
OPENWEBUI_IMAGE="${OPENWEBUI_IMAGE:-ghcr.io/open-webui/open-webui:v0.11.4-slim}"
AI_MIN_LOCAL_RAM_MIB="${AI_MIN_LOCAL_RAM_MIB:-6144}"
OLLAMA_MAX_LOADED_MODELS="${OLLAMA_MAX_LOADED_MODELS:-1}"
OLLAMA_NUM_PARALLEL="${OLLAMA_NUM_PARALLEL:-1}"
OLLAMA_KEEP_ALIVE="${OLLAMA_KEEP_ALIVE:-5m}"
AI_MODEL_MIN_FREE_GIB="${AI_MODEL_MIN_FREE_GIB:-35}"
OPENWEBUI_CF_PROXIED="${OPENWEBUI_CF_PROXIED:-0}"
OPENWEBUI_DNS_OVERWRITE="${OPENWEBUI_DNS_OVERWRITE:-0}"
WEBUI_ADMIN_NAME="${WEBUI_ADMIN_NAME:-p5n}"
WEBUI_ADMIN_EMAIL="${WEBUI_ADMIN_EMAIL:-}"
WEBUI_ADMIN_PASSWORD="${WEBUI_ADMIN_PASSWORD:-}"
ENABLE_WEB_SEARCH="${ENABLE_WEB_SEARCH:-true}"
WEB_SEARCH_ENGINE="${WEB_SEARCH_ENGINE:-exa}"
EXA_API_KEY="${EXA_API_KEY:-}"
WEB_LOADER_ENGINE="${WEB_LOADER_ENGINE:-firecrawl}"
FIRECRAWL_API_BASE_URL="${FIRECRAWL_API_BASE_URL:-https://api.firecrawl.dev}"
FIRECRAWL_API_KEY="${FIRECRAWL_API_KEY:-}"
ENABLE_WEB_SEARCH_CONFIRMATION="${ENABLE_WEB_SEARCH_CONFIRMATION:-false}"
ENABLE_SUBAGENTS="${ENABLE_SUBAGENTS:-true}"
SUBAGENTS_BACKGROUND_ENABLED="${SUBAGENTS_BACKGROUND_ENABLED:-true}"
SUBAGENTS_MAX_CONCURRENT="${SUBAGENTS_MAX_CONCURRENT:-4}"
SUBAGENTS_MAX_ASYNC="${SUBAGENTS_MAX_ASYNC:-4}"
SUBAGENTS_MAX_ITERATIONS="${SUBAGENTS_MAX_ITERATIONS:-30}"
SUBAGENTS_MAX_OUTPUT="${SUBAGENTS_MAX_OUTPUT:-30000}"
TASK_MODEL="${TASK_MODEL:-tev1:0.8b}"
WEBUI_URL="${WEBUI_URL:-auto}"
ENABLE_API_KEYS="${ENABLE_API_KEYS:-true}"
ENABLE_OLLAMA_API="${ENABLE_OLLAMA_API:-true}"
ENABLE_OPENAI_API="${ENABLE_OPENAI_API:-true}"
DEFAULT_MODEL_PARAMS="${DEFAULT_MODEL_PARAMS:-}"
DEFAULT_MODEL_METADATA="${DEFAULT_MODEL_METADATA:-}"
DEFAULT_INTERFACE_SETTINGS="${DEFAULT_INTERFACE_SETTINGS:-}"

[[ -n "$DEFAULT_MODEL_PARAMS" ]] || DEFAULT_MODEL_PARAMS='{"function_calling":"native"}'
[[ -n "$DEFAULT_MODEL_METADATA" ]] || DEFAULT_MODEL_METADATA='{"capabilities":{"web_search":true}}'
[[ -n "$DEFAULT_INTERFACE_SETTINGS" ]] || DEFAULT_INTERFACE_SETTINGS='{"webSearch":"always"}'
AI_ENABLED=0
AI_LOCAL_INFERENCE=0
AI_PROFILE="disabled"
AI_SELECTED_MODEL=""
AI_SELECTED_REASONING_MODEL=""
AI_SELECTED_DECISION_MODEL=""
OPENWEBUI_DOMAIN=""
: "${TAILSCALE_AUTH_KEY:?TAILSCALE_AUTH_KEY is required in .env}"
: "${GITHUB_TOKEN:?GITHUB_TOKEN is required in .env}"
: "${NEW_USER_PASSWORD:?NEW_USER_PASSWORD is required in .env}"
: "${GITHUB_USERNAME:=joeyqleq}"
: "${SOURCE_USER_OVERRIDE:=}"
: "${AAPANEL_PASSWORD:?AAPANEL_PASSWORD is required in .env}"
: "${AAPANEL_DOMAIN:?AAPANEL_DOMAIN is required in .env}"
: "${CLOUDFLARE_EMAIL:?CLOUDFLARE_EMAIL is required in .env}"
: "${CLOUDFLARE_API_KEY:?CLOUDFLARE_API_KEY is required in .env}"

# Export values used by aaPanel child runtimes even when they came from a shell default.
# Secrets stay out of command-line arguments/process listings.
export AAPANEL_USER AAPANEL_PASSWORD AAPANEL_DOMAIN
export CLOUDFLARE_EMAIL CLOUDFLARE_API_KEY CLOUDFLARE_ALIAS

# DNS names are case-insensitive; canonicalize the configured panel name so
# certificate names, Nginx files, and aaPanel's domain binding cannot diverge.
AAPANEL_DOMAIN="${AAPANEL_DOMAIN,,}"

# HOSTNAME is explicitly configurable in .env. For older .env files that do not
# contain it, derive a safe default from the aaPanel domain (e.g. goo2.example.com -> goo2).
if (( ENV_HAS_HOSTNAME )); then
  DESIRED_HOSTNAME="$HOSTNAME"
else
  DESIRED_HOSTNAME="${AAPANEL_DOMAIN%%.*}"
fi
[[ -n "$DESIRED_HOSTNAME" ]] || DESIRED_HOSTNAME="$TARGET_USER-vm"

mkdir -p "$STATE_DIR"
touch "$LOG_FILE"
chmod 600 "$LOG_FILE"
exec > >(tee -a "$LOG_FILE") 2>&1

CURRENT_STEP="startup"
STEP_WATCHDOG_PID=""
on_error() {
  local rc=$?
  if [[ -n "${STEP_WATCHDOG_PID:-}" ]]; then
    kill "$STEP_WATCHDOG_PID" >/dev/null 2>&1 || true
    wait "$STEP_WATCHDOG_PID" 2>/dev/null || true
    STEP_WATCHDOG_PID=""
  fi
  echo
  echo "================================================================"
  echo "BOOTSTRAP ERROR"
  echo "  step:    ${CURRENT_STEP}"
  echo "  line:    ${BASH_LINENO[0]:-unknown}"
  echo "  command: ${BASH_COMMAND}"
  echo "  code:    ${rc}"
  echo "  log:     ${LOG_FILE}"
  echo "================================================================"
  exit "$rc"
}
kill_descendants() {
  local parent="$1" sig="${2:-TERM}" child
  while read -r child; do
    [[ -n "$child" ]] || continue
    kill_descendants "$child" "$sig"
    kill -s "$sig" "$child" >/dev/null 2>&1 || true
  done < <(pgrep -P "$parent" 2>/dev/null || true)
}

on_interrupt() {
  local sig="${1:-INT}" rc=130
  [[ "$sig" == "TERM" ]] && rc=143
  trap - ERR INT TERM
  if [[ -n "${STEP_WATCHDOG_PID:-}" ]]; then
    kill "$STEP_WATCHDOG_PID" >/dev/null 2>&1 || true
    wait "$STEP_WATCHDOG_PID" 2>/dev/null || true
    STEP_WATCHDOG_PID=""
  fi
  printf '\n\033[1;31m[ABORT]\033[0m %s received during %s. Stopping child processes safely...\n' "$sig" "${CURRENT_STEP:-unknown}"
  kill_descendants "$$" TERM
  sleep 1
  kill_descendants "$$" KILL
  printf '\033[1;33m[RECOVER]\033[0m Completed checkpoints were preserved. Re-run and choose RECOVER.\n'
  exit "$rc"
}

trap on_error ERR
trap 'on_interrupt INT' INT
trap 'on_interrupt TERM' TERM

say() { printf '\n\033[1;36m==> %s\033[0m\n' "$*"; }
ok()  { printf '\033[1;32m[OK]\033[0m %s\n' "$*"; }
warn(){ printf '\033[1;33m[WARN]\033[0m %s\n' "$*"; }
die() { printf '\033[1;31m[FAIL]\033[0m %s\n' "$*" >&2; exit 1; }

start_step_watchdog() {
  local name="$1" interval="${STEP_WATCHDOG_SECONDS:-45}"
  [[ "$interval" =~ ^[0-9]+$ ]] || interval=45
  (( interval >= 10 )) || interval=10
  (
    local elapsed="$interval"
    while sleep "$interval"; do
      printf '\033[1;35m[WAIT]\033[0m %s is still running (%ss). Unattended steps should NOT require input. Silence can mean an installer is doing internal work; Ctrl-C aborts safely.\n' "$name" "$elapsed"
      elapsed=$((elapsed + interval))
    done
  ) &
  STEP_WATCHDOG_PID=$!
}

stop_step_watchdog() {
  if [[ -n "${STEP_WATCHDOG_PID:-}" ]]; then
    kill "$STEP_WATCHDOG_PID" >/dev/null 2>&1 || true
    wait "$STEP_WATCHDOG_PID" 2>/dev/null || true
    STEP_WATCHDOG_PID=""
  fi
}

cleanup_step_watchdog_on_exit() {
  # `die` uses exit rather than returning into the ERR trap. Without an EXIT
  # cleanup, the watchdog subshell inherits the log pipe and survives as an
  # orphan, producing endless [WAIT] lines after the real bootstrap is gone.
  if [[ -n "${STEP_WATCHDOG_PID:-}" ]]; then
    kill "$STEP_WATCHDOG_PID" >/dev/null 2>&1 || true
    wait "$STEP_WATCHDOG_PID" 2>/dev/null || true
    STEP_WATCHDOG_PID=""
  fi
}
trap cleanup_step_watchdog_on_exit EXIT

retry() {
  local attempts="$1"; shift
  local n=1 delay=2 rc=0
  while (( n <= attempts )); do
    if "$@"; then return 0; fi
    rc=$?
    if (( n == attempts )); then return "$rc"; fi
    warn "Attempt $n/$attempts failed (rc=$rc): $* ; retrying in ${delay}s"
    sleep "$delay"
    delay=$(( delay * 2 ))
    n=$(( n + 1 ))
  done
}

wait_for_apt() {
  local waited=0
  while fuser /var/lib/dpkg/lock-frontend /var/lib/dpkg/lock \
              /var/cache/apt/archives/lock /var/lib/apt/lists/lock \
              >/dev/null 2>&1; do
    (( waited % 10 == 0 )) && echo "Waiting for apt/dpkg lock... (${waited}s)"
    sleep 2
    waited=$(( waited + 2 ))
    if (( waited >= 600 )); then
      die "apt/dpkg lock did not clear within 10 minutes."
    fi
  done
}

apt_update() {
  wait_for_apt
  env DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=a APT_LISTCHANGES_FRONTEND=none \
    apt-get -o DPkg::Lock::Timeout=600 update -y
}

apt_install() {
  wait_for_apt
  env DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=a APT_LISTCHANGES_FRONTEND=none \
    apt-get -o DPkg::Lock::Timeout=600 install -y --no-install-recommends "$@"
}

apt_available() {
  # `apt-cache show` can succeed when package metadata exists but the package has
  # no installable candidate in the active Ubuntu release (notably libpcre3-dev
  # on Ubuntu 26.04). Check the resolver's Candidate instead.
  local candidate
  candidate="$(apt-cache policy "$1" 2>/dev/null | awk '/^[[:space:]]*Candidate:/ {print $2; exit}')"
  [[ -n "$candidate" && "$candidate" != "(none)" ]]
}

run_as_target() {
  # Never inherit the source/root account's working directory when executing
  # target-user commands. This is provider- and source-username independent.
  # It also prevents Homebrew from failing when bootstrap.sh was launched from
  # /root, a mode-0700 upload directory, or another unreadable path.
  local shell
  shell="$(getent passwd "$TARGET_USER" | cut -d: -f7)"
  [[ -n "$shell" ]] || shell=/bin/bash
  (
    cd "$TARGET_HOME"
    sudo -u "$TARGET_USER" -H -- env \
      HOME="$TARGET_HOME" USER="$TARGET_USER" LOGNAME="$TARGET_USER" SHELL="$shell" \
      PATH="$BREW_PREFIX/bin:$BREW_PREFIX/sbin:$TARGET_HOME/.local/bin:$TARGET_HOME/bin:/usr/local/bin:/usr/bin:/bin" \
      "$@"
  )
}

run_as_jq_bash() {
  run_as_target /bin/bash -lc "cd \"$TARGET_HOME\" && $1"
}

run_as_target_auto_yes() {
  # Some third-party installers/formulae can still ask for confirmation even
  # when CI/NONINTERACTIVE are set. Use a bounded regular file rather than an
  # infinite `yes` pipe. This avoids SIGPIPE/EBADF noise from Homebrew's Ruby
  # sandbox while still providing enough confirmations for unattended setup.
  local answers rc=0 i
  answers="$(mktemp)"
  for ((i=0; i<64; i++)); do
    printf 'y\n'
  done > "$answers"
  chmod 0644 "$answers"
  set +e
  run_as_target "$@" < "$answers"
  rc=$?
  set -e
  rm -f "$answers"
  return "$rc"
}

mark_done() { touch "$STATE_DIR/$1.done"; }

INSTALL_MODE="${BOOTSTRAP_MODE:-}"
choose_install_mode() {
  if [[ "$INSTALL_MODE" == "fresh" || "$INSTALL_MODE" == "recovery" ]]; then
    return 0
  fi

  printf '
\033[1;36m╔══════════════════════════════════════════════════════╗\033[0m
'
  printf '\033[1;36m║               jq UNIVERSAL BOOTSTRAP                ║\033[0m
'
  printf '\033[1;36m╚══════════════════════════════════════════════════════╝\033[0m

'
  printf '  \033[1;32m[1] FRESH\033[0m    New VM / install the complete stack
'
  printf '  \033[1;33m[2] RECOVER\033[0m  Previous run broke / inspect and continue safely

'

  if [[ ! -t 0 ]]; then
    if compgen -G "$STATE_DIR/*.done" >/dev/null 2>&1; then
      INSTALL_MODE="recovery"
    else
      INSTALL_MODE="fresh"
    fi
    warn "No interactive terminal; auto-selected $INSTALL_MODE mode."
    return 0
  fi

  local answer
  while true; do
    read -r -p 'Choose [1/2]: ' answer
    case "$answer" in
      1|fresh|FRESH) INSTALL_MODE="fresh"; break ;;
      2|recover|RECOVER|recovery|RECOVERY) INSTALL_MODE="recovery"; break ;;
      *) echo 'Enter 1 for Fresh or 2 for Recover.' ;;
    esac
  done

  if [[ "$INSTALL_MODE" == "fresh" ]]; then
    rm -f "$STATE_DIR"/*.done 2>/dev/null || true
    ok "Fresh mode selected. Steps will be applied in order and verified."
  else
    ok "Recovery mode selected. Existing system state will be verified before each action."
  fi
}

normalize_yes_no() {
  case "${1,,}" in
    1|y|yes|true|on|enabled) printf '1\n' ;;
    0|n|no|false|off|disabled|'') printf '0\n' ;;
    *) return 1 ;;
  esac
}

ai_hardware_profile() {
  local mem_mib cpus free_gib
  mem_mib=$(( $(awk '/MemTotal:/ {print $2}' /proc/meminfo) / 1024 ))
  cpus="$(nproc)"
  free_gib="$(df -Pk / | awk 'NR==2 {print int($4/1024/1024)}')"
  AI_RAM_MIB="$mem_mib"
  AI_CPUS="$cpus"
  AI_FREE_GIB="$free_gib"

  if (( mem_mib < AI_MIN_LOCAL_RAM_MIB )); then
    AI_PROFILE="gateway-only"
    AI_LOCAL_INFERENCE=0
    AI_SELECTED_MODEL=""
    AI_SELECTED_REASONING_MODEL=""
    return 0
  fi

  AI_LOCAL_INFERENCE=1
  if [[ "$AI_PRIMARY_MODEL" != "auto" ]]; then
    AI_SELECTED_MODEL="$AI_PRIMARY_MODEL"
    AI_PROFILE="custom"
  elif (( mem_mib >= 20000 )); then
    AI_SELECTED_MODEL="qwen3.5:9b"
    AI_PROFILE="worker-xl"
  elif (( mem_mib >= 10000 )); then
    AI_SELECTED_MODEL="qwen3.5:4b"
    AI_PROFILE="worker-large"
  else
    AI_SELECTED_MODEL="qwen3.5:4b"
    AI_PROFILE="worker-standard"
  fi

  AI_SELECTED_REASONING_MODEL=""
  if (( mem_mib >= 20000 )) && [[ "$(normalize_yes_no "$AI_PULL_REASONING_MODEL" 2>/dev/null || echo 0)" == "1" ]] && (( free_gib >= AI_MODEL_MIN_FREE_GIB )); then
    AI_SELECTED_REASONING_MODEL="$AI_REASONING_MODEL"
  fi
}

persist_ai_mode() {
  install -d -m 0700 "$STATE_DIR"
  {
    printf 'AI_ENABLED=%q\n' "$AI_ENABLED"
    printf 'AI_LOCAL_INFERENCE=%q\n' "$AI_LOCAL_INFERENCE"
    printf 'AI_PROFILE=%q\n' "$AI_PROFILE"
    printf 'AI_SELECTED_MODEL=%q\n' "$AI_SELECTED_MODEL"
    printf 'AI_SELECTED_REASONING_MODEL=%q\n' "$AI_SELECTED_REASONING_MODEL"
    printf 'AI_SELECTED_DECISION_MODEL=%q\n' "${AI_SELECTED_DECISION_MODEL:-}"
  } > "$STATE_DIR/ai-mode.env"
  chmod 600 "$STATE_DIR/ai-mode.env"
}

choose_ai_mode() {
  local persisted="$STATE_DIR/ai-mode.env" configured answer normalized

  # Recovery keeps the original machine role unless the .env explicitly forces
  # AI_INFERENCE_MODE to yes/no. This prevents a recovery run from unexpectedly
  # pulling tens of gigabytes of models.
  if [[ "$INSTALL_MODE" == "recovery" && -r "$persisted" && "${AI_INFERENCE_MODE,,}" == "ask" ]]; then
    # shellcheck disable=SC1090
    source "$persisted"
    ai_hardware_profile
    if (( AI_ENABLED == 0 )); then
      AI_LOCAL_INFERENCE=0; AI_PROFILE="disabled"; AI_SELECTED_MODEL=""; AI_SELECTED_REASONING_MODEL=""; AI_SELECTED_DECISION_MODEL=""
    else
      AI_SELECTED_DECISION_MODEL=""
      if [[ "$(normalize_yes_no "$AI_PULL_DECISION_MODEL" 2>/dev/null || echo 0)" == "1" ]]; then
        AI_SELECTED_DECISION_MODEL="$AI_DECISION_MODEL"
      fi
    fi
    persist_ai_mode
    ok "AI mode recovered: ${AI_ENABLED} (${AI_PROFILE})."
    return 0
  fi

  configured="${AI_INFERENCE_MODE,,}"
  if [[ "$configured" != "ask" ]]; then
    normalized="$(normalize_yes_no "$configured")" || die "AI_INFERENCE_MODE must be ask, yes/1/on, or no/0/off."
    AI_ENABLED="$normalized"
  elif [[ "$INSTALL_MODE" == "fresh" && -t 0 ]]; then
    printf '\n'
    read -r -p 'Include AI inference stack (Codex + OpenWebUI + Ollama + models)? [y/N]: ' answer
    AI_ENABLED="$(normalize_yes_no "${answer:-no}" 2>/dev/null || echo 0)"
  else
    AI_ENABLED=0
    warn "AI_INFERENCE_MODE=ask but no interactive terminal is available; AI mode disabled. Set AI_INFERENCE_MODE=1 to force it."
  fi

  ai_hardware_profile
  AI_SELECTED_DECISION_MODEL=""
  if [[ "$(normalize_yes_no "$AI_PULL_DECISION_MODEL" 2>/dev/null || echo 0)" == "1" ]]; then
    AI_SELECTED_DECISION_MODEL="$AI_DECISION_MODEL"
  fi
  if (( AI_ENABLED == 0 )); then
    AI_LOCAL_INFERENCE=0
    AI_PROFILE="disabled"
    AI_SELECTED_MODEL=""
    AI_SELECTED_REASONING_MODEL=""
    AI_SELECTED_DECISION_MODEL=""
    ok "AI inference mode disabled."
  elif (( AI_LOCAL_INFERENCE == 0 )); then
    warn "AI mode enabled, but ${AI_RAM_MIB} MiB RAM is below ${AI_MIN_LOCAL_RAM_MIB} MiB. Configuring gateway/router mode: Codex + Ollama decision service only; OpenWebUI and general-purpose models will be skipped."
  else
    ok "AI inference mode enabled: ${AI_PROFILE}, ${AI_RAM_MIB} MiB RAM, ${AI_CPUS} CPUs; primary model ${AI_SELECTED_MODEL}."
    [[ -z "$AI_SELECTED_REASONING_MODEL" ]] || ok "Secondary cached reasoning model: ${AI_SELECTED_REASONING_MODEL}."
  fi
  [[ -z "${AI_SELECTED_DECISION_MODEL:-}" ]] || ok "Decision/routing model: ${AI_SELECTED_DECISION_MODEL}."
  persist_ai_mode
}

run_step() {
  local name="$1" verify_fn="$2" action_fn="$3"
  CURRENT_STEP="$name"
  say "$name"

  # Recovery trusts live system state, not merely a checkpoint file. This
  # makes partial/no-checkpoint failures safe to resume.
  if [[ "$INSTALL_MODE" == "recovery" ]]; then
    if "$verify_fn"; then
      mark_done "$name"
      ok "$name verified complete; skipping."
      return 0
    fi
    if [[ -f "$STATE_DIR/$name.done" ]]; then
      warn "$name checkpoint exists but live verification failed; repairing."
      rm -f "$STATE_DIR/$name.done"
    else
      warn "$name is incomplete or partially applied; repairing."
    fi
  elif [[ -f "$STATE_DIR/$name.done" ]]; then
    if "$verify_fn"; then
      ok "$name already complete."
      return 0
    fi
    warn "$name checkpoint exists but verification failed; repairing."
    rm -f "$STATE_DIR/$name.done"
  fi

  printf '\033[1;34m[RUN]\033[0m %s: live installer output follows.\n' "$name"
  start_step_watchdog "$name"
  "$action_fn"
  stop_step_watchdog
  if ! "$verify_fn"; then
    die "$name action completed but verification failed."
  fi
  mark_done "$name"
  ok "$name complete."
}

# ---------------------------------------------------------------------------
# Preflight and source SSH-key discovery
# ---------------------------------------------------------------------------

SOURCE_USER=""
SOURCE_HOME=""
SOURCE_AUTH_KEYS=""

detect_source_user() {
  local candidate="" home="" key="" u=""
  local -a candidates=() key_users=()

  candidate_has_key() {
    local cu="$1" ch=""
    [[ -n "$cu" && "$cu" != "root" ]] || return 1
    getent passwd "$cu" >/dev/null 2>&1 || return 1
    ch="$(getent passwd "$cu" | cut -d: -f6)"
    [[ -n "$ch" && -s "$ch/.ssh/authorized_keys" ]]
  }

  add_candidate() {
    local cu="${1:-}"
    [[ -n "$cu" && "$cu" != "root" ]] || return 0
    local x
    for x in "${candidates[@]:-}"; do [[ "$x" == "$cu" ]] && return 0; done
    candidates+=("$cu")
  }

  # Strongest signals first. BOOTSTRAP_INVOKER is captured before this script
  # self-elevates, so arbitrary GCE/Oracle/AWS/custom usernames work unchanged.
  add_candidate "$SOURCE_USER_OVERRIDE"
  add_candidate "${BOOTSTRAP_INVOKER:-}"
  add_candidate "${SUDO_USER:-}"

  # These cover users who first opened an interactive root shell and only then
  # launched the bootstrap.
  if command -v logname >/dev/null 2>&1; then
    add_candidate "$(logname 2>/dev/null || true)"
  fi
  if command -v who >/dev/null 2>&1; then
    add_candidate "$(who am i 2>/dev/null | awk '{print $1}' || true)"
  fi

  # Walk the process ancestry and collect non-root process owners. This catches
  # sudo/su wrappers where SUDO_USER/logname are missing but the SSH session is
  # still visible in the parent chain.
  local pid="$$" ppid="" owner="" i=0
  while [[ "$pid" =~ ^[0-9]+$ ]] && (( pid > 1 )) && (( i < 24 )); do
    owner="$(ps -o user= -p "$pid" 2>/dev/null | xargs || true)"
    add_candidate "$owner"
    ppid="$(ps -o ppid= -p "$pid" 2>/dev/null | xargs || true)"
    [[ "$ppid" =~ ^[0-9]+$ ]] || break
    pid="$ppid"
    i=$((i+1))
  done

  for candidate in "${candidates[@]:-}"; do
    if candidate_has_key "$candidate"; then
      SOURCE_USER="$candidate"
      SOURCE_HOME="$(getent passwd "$candidate" | cut -d: -f6)"
      SOURCE_AUTH_KEYS="$SOURCE_HOME/.ssh/authorized_keys"
      return 0
    fi
  done

  # Recovery after jq has already been created: its copied key is authoritative
  # enough to continue even if the original cloud account is no longer obvious.
  if candidate_has_key "$TARGET_USER"; then
    SOURCE_USER="$TARGET_USER"
    SOURCE_HOME="$(getent passwd "$TARGET_USER" | cut -d: -f6)"
    SOURCE_AUTH_KEYS="$SOURCE_HOME/.ssh/authorized_keys"
    return 0
  fi

  # Last resort: inventory all real /home users with a usable authorized_keys.
  while IFS= read -r key; do
    home="${key%/.ssh/authorized_keys}"
    u="${home##*/}"
    getent passwd "$u" >/dev/null 2>&1 || continue
    key_users+=("$u")
  done < <(find /home -mindepth 3 -maxdepth 3 -type f \
             -path '/home/*/.ssh/authorized_keys' -size +0c 2>/dev/null | sort -u)

  if (( ${#key_users[@]} == 1 )); then
    SOURCE_USER="${key_users[0]}"
    SOURCE_HOME="$(getent passwd "$SOURCE_USER" | cut -d: -f6)"
    SOURCE_AUTH_KEYS="$SOURCE_HOME/.ssh/authorized_keys"
    return 0
  fi

  printf 'Detected SSH-key users: %s\n' "${key_users[*]:-(none)}" >&2
  die "Could not safely determine which SSH key account is the bootstrap source. Set SOURCE_USER_OVERRIDE only for this genuinely ambiguous case."
}

preflight() {
  [[ -r /etc/os-release ]] || die "Cannot identify the operating system."
  # shellcheck disable=SC1091
  source /etc/os-release
  [[ "${ID:-}" == "ubuntu" ]] || die "This bootstrap intentionally supports fresh Ubuntu only (detected ${ID:-unknown})."
  [[ "$(uname -m)" =~ ^(x86_64|aarch64|arm64)$ ]] || die "Unsupported CPU architecture: $(uname -m)"

  detect_source_user
  [[ -s "$SOURCE_AUTH_KEYS" ]] || die "Source authorized_keys is missing/empty: $SOURCE_AUTH_KEYS"

  say "Detected bootstrap source"
  echo "Ubuntu:        ${PRETTY_NAME:-unknown}"
  echo "Source user:   $SOURCE_USER"
  echo "Source home:   $SOURCE_HOME"
  echo "SSH key file:  $SOURCE_AUTH_KEYS"
  echo "Target user:   $TARGET_USER"
  echo "Target home:   $TARGET_HOME"

  if [[ "${VERSION_ID:-}" != "22.04" && "${VERSION_ID:-}" != "24.04" && "${VERSION_ID:-}" != "26.04" ]]; then
    warn "aaPanel currently documents Ubuntu 22/24 most explicitly; detected ${VERSION_ID:-unknown}. The install step will self-verify."
  fi
}

verify_preflight() {
  [[ -n "$SOURCE_USER" && -n "$SOURCE_HOME" && -s "$SOURCE_AUTH_KEYS" ]]
}

do_preflight() { preflight; }

# ---------------------------------------------------------------------------
# Swap + low-memory tuning
# ---------------------------------------------------------------------------

memory_profile() {
  local mem_mib desired swappiness cache_pressure dirty_bg dirty
  mem_mib=$(( $(awk '/MemTotal:/ {print $2}' /proc/meminfo) / 1024 ))

  # Swap is a safety net, not an extension of model RAM. Even large cloud VMs
  # get some swap so a transient compile/model spike invokes reclamation rather
  # than the OOM killer. The low swappiness on >=8 GiB keeps normal workloads in RAM.
  if (( mem_mib <= 1280 )); then
    desired=2048; swappiness=35; cache_pressure=80; dirty_bg=5; dirty=15
    MEMORY_PROFILE="tiny"
  elif (( mem_mib <= 2560 )); then
    desired=1536; swappiness=25; cache_pressure=70; dirty_bg=5; dirty=15
    MEMORY_PROFILE="small"
  elif (( mem_mib <= 4096 )); then
    desired=2048; swappiness=20; cache_pressure=60; dirty_bg=5; dirty=15
    MEMORY_PROFILE="medium"
  elif (( mem_mib <= 8192 )); then
    desired=2048; swappiness=15; cache_pressure=50; dirty_bg=5; dirty=15
    MEMORY_PROFILE="normal"
  elif (( mem_mib <= 16384 )); then
    desired=2048; swappiness=10; cache_pressure=50; dirty_bg=5; dirty=15
    MEMORY_PROFILE="large"
  else
    desired=4096; swappiness=10; cache_pressure=50; dirty_bg=5; dirty=15
    MEMORY_PROFILE="xlarge"
  fi

  RAM_MIB="$mem_mib"
  DESIRED_SWAP_MIB="${SWAP_SIZE_MIB_OVERRIDE:-$desired}"
  PROFILE_SWAPPINESS="${VM_SWAPPINESS_OVERRIDE:-$swappiness}"
  PROFILE_CACHE_PRESSURE="${VM_VFS_CACHE_PRESSURE_OVERRIDE:-$cache_pressure}"
  PROFILE_DIRTY_BG="${VM_DIRTY_BACKGROUND_RATIO_OVERRIDE:-$dirty_bg}"
  PROFILE_DIRTY="${VM_DIRTY_RATIO_OVERRIDE:-$dirty}"
}

verify_swap() {
  memory_profile
  [[ -f /etc/sysctl.d/99-jq-low-memory.conf ]] || return 1
  grep -Fxq "vm.swappiness=$PROFILE_SWAPPINESS" /etc/sysctl.d/99-jq-low-memory.conf || return 1
  grep -Fxq "vm.vfs_cache_pressure=$PROFILE_CACHE_PRESSURE" /etc/sysctl.d/99-jq-low-memory.conf || return 1

  if (( DESIRED_SWAP_MIB == 0 )); then
    # An explicit SWAP_SIZE_MIB_OVERRIDE=0 disables the swapfile requirement.
    return 0
  fi

  [[ -f "$SWAP_FILE" ]] || return 1
  local current_mib
  current_mib=$(( $(stat -c %s "$SWAP_FILE") / 1024 / 1024 ))
  (( current_mib >= DESIRED_SWAP_MIB )) || return 1
  swapon --show=NAME --noheadings | grep -Fxq "$SWAP_FILE" || return 1
  grep -Eq "^${SWAP_FILE//\//\\/}[[:space:]]+none[[:space:]]+swap[[:space:]]" /etc/fstab
}

setup_swap() {
  memory_profile
  say "Memory profile: ${MEMORY_PROFILE} (${RAM_MIB} MiB RAM, target swap ${DESIRED_SWAP_MIB} MiB)"

  if (( DESIRED_SWAP_MIB > 0 )); then
    local current_mib=0
    if [[ -f "$SWAP_FILE" ]]; then
      current_mib=$(( $(stat -c %s "$SWAP_FILE") / 1024 / 1024 ))
    fi

    # Never shrink a healthy larger swapfile during recovery. Resize only when
    # missing or smaller than the profile requires.
    if [[ ! -f "$SWAP_FILE" || "$current_mib" -lt "$DESIRED_SWAP_MIB" ]]; then
      swapoff "$SWAP_FILE" 2>/dev/null || true
      rm -f "$SWAP_FILE"
      if ! fallocate -l "${DESIRED_SWAP_MIB}M" "$SWAP_FILE" 2>/dev/null; then
        dd if=/dev/zero of="$SWAP_FILE" bs=1M count="$DESIRED_SWAP_MIB" status=progress
      fi
      chmod 600 "$SWAP_FILE"
      mkswap "$SWAP_FILE" >/dev/null
    else
      chmod 600 "$SWAP_FILE"
      if ! file "$SWAP_FILE" | grep -qi 'swap file'; then
        swapoff "$SWAP_FILE" 2>/dev/null || true
        mkswap "$SWAP_FILE" >/dev/null
      fi
    fi

    swapon --show=NAME --noheadings | grep -Fxq "$SWAP_FILE" || swapon "$SWAP_FILE"
    grep -Eq "^${SWAP_FILE//\//\\/}[[:space:]]" /etc/fstab ||
      printf '%s none swap sw 0 0\n' "$SWAP_FILE" >> /etc/fstab
  fi

  cat > /etc/sysctl.d/99-jq-low-memory.conf <<SYSCTL
# Auto-selected by jq bootstrap for ${RAM_MIB} MiB RAM (${MEMORY_PROFILE} profile).
vm.swappiness=${PROFILE_SWAPPINESS}
vm.vfs_cache_pressure=${PROFILE_CACHE_PRESSURE}
vm.dirty_background_ratio=${PROFILE_DIRTY_BG}
vm.dirty_ratio=${PROFILE_DIRTY}
net.ipv4.tcp_keepalive_time=600
net.ipv4.tcp_keepalive_intvl=60
net.ipv4.tcp_keepalive_probes=10
SYSCTL
  sysctl --system >/dev/null

  cat > "$STATE_DIR/memory-profile.env" <<PROFILE
RAM_MIB=${RAM_MIB}
MEMORY_PROFILE=${MEMORY_PROFILE}
DESIRED_SWAP_MIB=${DESIRED_SWAP_MIB}
PROFILE_SWAPPINESS=${PROFILE_SWAPPINESS}
PROFILE_CACHE_PRESSURE=${PROFILE_CACHE_PRESSURE}
PROFILE_DIRTY_BG=${PROFILE_DIRTY_BG}
PROFILE_DIRTY=${PROFILE_DIRTY}
PROFILE
  chmod 600 "$STATE_DIR/memory-profile.env"
}

# ---------------------------------------------------------------------------
# Base apt stack. Zsh + Docker/Compose are deliberately installed before jq.
# ---------------------------------------------------------------------------

verify_base_packages() {
  command -v zsh >/dev/null &&
  command -v docker >/dev/null &&
  docker compose version >/dev/null 2>&1 &&
  command -v python3 >/dev/null &&
  command -v eza >/dev/null &&
  command -v lsof >/dev/null &&
  command -v netstat >/dev/null &&
  command -v ping >/dev/null &&
  command -v gh >/dev/null
}

setup_github_apt_repo() {
  install -d -m 0755 /etc/apt/keyrings /etc/apt/sources.list.d
  retry 3 curl -fsSL https://cli.github.com/packages/githubcli-archive-keyring.gpg \
    -o /etc/apt/keyrings/githubcli-archive-keyring.gpg
  chmod go+r /etc/apt/keyrings/githubcli-archive-keyring.gpg
  printf 'deb [arch=%s signed-by=/etc/apt/keyrings/githubcli-archive-keyring.gpg] https://cli.github.com/packages stable main\n' \
    "$(dpkg --print-architecture)" > /etc/apt/sources.list.d/github-cli.list
}

setup_base_packages() {
  apt_update
  apt_install ca-certificates curl wget gnupg gpg lsb-release \
    software-properties-common apt-transport-https

  # eza is in Ubuntu Universe on current LTS releases.
  add-apt-repository -y universe >/dev/null 2>&1 || true
  setup_github_apt_repo
  apt_update

  apt_install \
    zsh git build-essential pkg-config \
    python3 python3-pip python3-venv python3-dev python3-pygments python3-pil \
    fontconfig fonts-dejavu-core \
    docker.io \
    eza lsof net-tools iputils-ping iproute2 dnsutils traceroute mtr-tiny \
    nano less tree htop ncdu tmux direnv rsync unzip zip tar psmisc \
    jq expect sqlite3 util-linux file locales gh certbot python3-certbot-dns-cloudflare

  if apt_available docker-compose-v2; then
    apt_install docker-compose-v2
  elif apt_available docker-compose-plugin; then
    apt_install docker-compose-plugin
  elif apt_available docker-compose; then
    apt_install docker-compose
  else
    die "No Docker Compose package is available through apt on this Ubuntu image."
  fi

  systemctl enable --now docker

  # Bound Docker's default json-file logs so a tiny VM does not slowly fill disk.
  install -d -m 0755 /etc/docker
  if [[ -s /etc/docker/daemon.json ]]; then
    /usr/bin/jq \
      '. + {"log-driver":"json-file","log-opts":{"max-size":"10m","max-file":"3"}}' \
      /etc/docker/daemon.json > /etc/docker/daemon.json.tmp
    mv /etc/docker/daemon.json.tmp /etc/docker/daemon.json
  else
    cat > /etc/docker/daemon.json <<'DOCKERJSON'
{
  "log-driver": "json-file",
  "log-opts": {
    "max-size": "10m",
    "max-file": "3"
  }
}
DOCKERJSON
  fi
  systemctl restart docker
}

# ---------------------------------------------------------------------------
# Global default shell (without triggering zsh-newuser-install)
# ---------------------------------------------------------------------------

verify_global_zsh() {
  local zsh_bin
  zsh_bin="$(command -v zsh)"
  [[ "$(useradd -D | awk -F= '$1=="SHELL"{print $2}')" == "$zsh_bin" ]] &&
  [[ "$(getent passwd "$SOURCE_USER" | cut -d: -f7)" == "$zsh_bin" ]]
}

setup_global_zsh() {
  local zsh_bin user home
  zsh_bin="$(command -v zsh)"
  grep -Fxq "$zsh_bin" /etc/shells || echo "$zsh_bin" >> /etc/shells

  # Future users.
  useradd -D -s "$zsh_bin"
  if [[ -f /etc/adduser.conf ]]; then
    if grep -q '^DSHELL=' /etc/adduser.conf; then
      sed -i "s|^DSHELL=.*|DSHELL=$zsh_bin|" /etc/adduser.conf
    else
      printf '\nDSHELL=%s\n' "$zsh_bin" >> /etc/adduser.conf
    fi
  fi

  # Existing normal cloud users. Creating an empty .zshrc first is intentional:
  # it suppresses zsh-newuser-install if this bootstrap aborts before completion.
  while IFS=: read -r user _ uid _ _ home shell; do
    (( uid >= 1000 && uid < 60000 )) || continue
    [[ -d "$home" ]] || continue
    if [[ ! -e "$home/.zshrc" && ! -e "$home/.zshenv" ]]; then
      install -m 0644 -o "$user" -g "$(id -gn "$user")" /dev/null "$home/.zshrc"
    fi
    usermod -s "$zsh_bin" "$user"
  done < <(getent passwd)
}

# ---------------------------------------------------------------------------
# jq account + passwordless sudo + migrated SSH key
# ---------------------------------------------------------------------------

verify_user() {
  id "$TARGET_USER" >/dev/null 2>&1 &&
  id -nG "$TARGET_USER" | tr ' ' '\n' | grep -Fxq sudo &&
  id -nG "$TARGET_USER" | tr ' ' '\n' | grep -Fxq docker &&
  [[ "$(getent passwd "$TARGET_USER" | cut -d: -f7)" == "$(command -v zsh)" ]] &&
  [[ -s "$TARGET_HOME/.ssh/authorized_keys" ]] &&
  [[ "$(stat -c '%U:%G:%a' "$TARGET_HOME/.ssh")" == "$TARGET_USER:$TARGET_USER:700" ]] &&
  [[ "$(stat -c '%U:%G:%a' "$TARGET_HOME/.ssh/authorized_keys")" == "$TARGET_USER:$TARGET_USER:600" ]] &&
  tail -n 20 /etc/sudoers | grep -Fxq 'jq ALL=(ALL:ALL) NOPASSWD: ALL' &&
  visudo -cf /etc/sudoers >/dev/null
}

setup_user() {
  local zsh_bin
  zsh_bin="$(command -v zsh)"

  getent group docker >/dev/null || groupadd docker

  if ! id "$TARGET_USER" >/dev/null 2>&1; then
    useradd -m -s "$zsh_bin" "$TARGET_USER"
  else
    usermod -s "$zsh_bin" "$TARGET_USER"
  fi

  echo "$TARGET_USER:$NEW_USER_PASSWORD" | chpasswd
  usermod -aG sudo,docker "$TARGET_USER"

  install -d -m 0700 -o "$TARGET_USER" -g "$TARGET_USER" "$TARGET_HOME/.ssh"
  install -m 0600 -o "$TARGET_USER" -g "$TARGET_USER" \
    "$SOURCE_AUTH_KEYS" "$TARGET_HOME/.ssh/authorized_keys"

  # User explicitly requested this exact line at the end of the main sudoers file.
  sed -i '\|^jq ALL=(ALL:ALL) NOPASSWD: ALL$|d' /etc/sudoers
  printf '\njq ALL=(ALL:ALL) NOPASSWD: ALL\n' >> /etc/sudoers
  chmod 0440 /etc/sudoers
  visudo -cf /etc/sudoers >/dev/null

  install -d -m 0755 -o "$TARGET_USER" -g "$TARGET_USER" \
    "$TARGET_HOME/Downloads" "$TARGET_HOME/bin"
}

# ---------------------------------------------------------------------------
# Tailscale: official installer sets up apt repo/package; auth key is from .env
# ---------------------------------------------------------------------------

verify_tailscale() {
  command -v tailscale >/dev/null &&
  systemctl is-active --quiet tailscaled &&
  tailscale status --json 2>/dev/null | /usr/bin/jq -e '.BackendState == "Running"' >/dev/null
}

setup_tailscale() {
  if ! command -v tailscale >/dev/null; then
    retry 3 bash -c 'curl -fsSL https://tailscale.com/install.sh | sh'
  fi

  systemctl enable --now tailscaled

  if ! tailscale status --json 2>/dev/null | /usr/bin/jq -e '.BackendState == "Running"' >/dev/null; then
    # Never print the auth key and never enable shell xtrace.
    tailscale up \
      --auth-key="$TAILSCALE_AUTH_KEY" \
      --advertise-exit-node
  fi
}

# ---------------------------------------------------------------------------
# Homebrew + zplug + Ox + current GitHub Copilot CLI
# ---------------------------------------------------------------------------

verify_homebrew() {
  [[ -x "$BREW_BIN" ]] &&
  run_as_target "$BREW_BIN" list zplug >/dev/null 2>&1 &&
  run_as_target "$BREW_BIN" list ox >/dev/null 2>&1 &&
  [[ -x "$BREW_PREFIX/bin/ox" ]] &&
  [[ -x "$BREW_PREFIX/bin/copilot" ]]
}

setup_homebrew() {
  local -a brew_env=(
    env CI=1 NONINTERACTIVE=1
    HOMEBREW_NO_ENV_HINTS=1
    HOMEBREW_NO_ANALYTICS=1
  )

  if [[ ! -x "$BREW_BIN" ]]; then
    printf '\033[1;34m[AUTO]\033[0m Homebrew installer is forced non-interactive.\n'
    run_as_target env NONINTERACTIVE=1 CI=1 /bin/bash -c \
      'curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh | /bin/bash'
  fi

  # Keep update visible but never let an update-only failure block recovery.
  run_as_target "${brew_env[@]}" "$BREW_BIN" update || true

  if [[ "$HOMEBREW_AUTO_YES" == "1" ]]; then
    printf '\033[1;34m[AUTO]\033[0m Auto-answering YES to any Homebrew confirmation while installing zplug/ox.\n'
    run_as_target_auto_yes "${brew_env[@]}" "$BREW_BIN" install zplug ox
  else
    run_as_target "${brew_env[@]}" "$BREW_BIN" install zplug ox
  fi

  # The old github/gh-copilot extension is retired. GitHub's supported CLI is
  # now the standalone Copilot CLI, and `gh copilot` dispatches to it.
  if [[ ! -x "$BREW_PREFIX/bin/copilot" ]]; then
    if [[ "$HOMEBREW_AUTO_YES" == "1" ]]; then
      printf '\033[1;34m[AUTO]\033[0m Auto-answering YES to any Copilot CLI cask confirmation.\n'
      if ! run_as_target_auto_yes "${brew_env[@]}" "$BREW_BIN" install --cask copilot-cli; then
        warn "Homebrew cask install failed; using GitHub's official Copilot CLI install script fallback."
        run_as_target env NONINTERACTIVE=1 CI=1 PREFIX="$BREW_PREFIX" /bin/bash -lc \
          'curl -fsSL https://gh.io/copilot-install | bash'
      fi
    else
      if ! run_as_target "${brew_env[@]}" "$BREW_BIN" install --cask copilot-cli; then
        warn "Homebrew cask install failed; using GitHub's official Copilot CLI install script fallback."
        run_as_target env NONINTERACTIVE=1 CI=1 PREFIX="$BREW_PREFIX" /bin/bash -lc \
          'curl -fsSL https://gh.io/copilot-install | bash'
      fi
    fi
  fi
}

# ---------------------------------------------------------------------------
# GitHub CLI credential setup
# ---------------------------------------------------------------------------

# Cloud VMs under load can suffer transient GitHub TLS handshake timeouts.
# Retry reads without ever printing tokens or confusing network errors with
# invalid credentials. Only a verified account login passes this check.
github_api_login() {
  local n login
  for n in 1 2 3; do
    login="$(run_as_target timeout 30 gh api user --jq .login 2>/dev/null)" &&
      [[ -n "$login" ]] && { printf '%s\n' "$login"; return 0; }
    (( n == 3 )) || sleep "$n"
  done
  return 1
}

verify_github() {
  local login
  login="$(github_api_login || true)"
  [[ "$login" == "$GITHUB_USERNAME" ]] &&
  run_as_target timeout 30 gh auth status --hostname github.com >/dev/null 2>&1
}

setup_github() {
  local ghdir="$TARGET_HOME/.config/gh"
  install -d -m 0700 -o "$TARGET_USER" -g "$TARGET_USER" "$ghdir"

  # Fine-grained PATs are best used headlessly. This is the same host config
  # file gh uses when no OS keyring is available.
  {
    printf 'github.com:\n'
    printf '    user: %s\n' "$GITHUB_USERNAME"
    printf '    oauth_token: %s\n' "$GITHUB_TOKEN"
    printf '    git_protocol: https\n'
  } > "$ghdir/hosts.yml"
  chown "$TARGET_USER:$TARGET_USER" "$ghdir/hosts.yml"
  chmod 0600 "$ghdir/hosts.yml"

  run_as_target gh config set git_protocol https --host github.com
  run_as_target gh auth setup-git
  run_as_target git config --global color.ui auto

  local login
  login="$(github_api_login)" || die "GitHub authentication API did not respond after retries."
  [[ "$login" == "$GITHUB_USERNAME" ]] ||
    die "GitHub token authenticated as '$login', expected '$GITHUB_USERNAME'."
}

# ---------------------------------------------------------------------------
# Python venv + Portsey
# ---------------------------------------------------------------------------

verify_venv() {
  [[ -x "$TARGET_HOME/myvenv/bin/python" ]] &&
  "$TARGET_HOME/myvenv/bin/python" -c 'import pip' >/dev/null 2>&1
}

setup_venv() {
  if [[ ! -x "$TARGET_HOME/myvenv/bin/python" ]]; then
    rm -rf "$TARGET_HOME/myvenv"
    run_as_target python3 -m venv "$TARGET_HOME/myvenv"
  fi
  run_as_target "$TARGET_HOME/myvenv/bin/python" -m pip \
    install --upgrade pip setuptools wheel
}

verify_portsey() {
  [[ -d "$TARGET_HOME/Portsey/.git" ]] &&
  [[ -f "$TARGET_HOME/Portsey/requirements.txt" ]] &&
  "$TARGET_HOME/myvenv/bin/python" -c 'import requests, rich, pyfiglet' >/dev/null 2>&1
}

setup_portsey() {
  if [[ -d "$TARGET_HOME/Portsey/.git" ]]; then
    run_as_target git -C "$TARGET_HOME/Portsey" fetch --all --prune
    run_as_target git -C "$TARGET_HOME/Portsey" pull --ff-only || true
  else
    rm -rf "$TARGET_HOME/Portsey"
    run_as_target git clone "$PORTSEY_REPO" "$TARGET_HOME/Portsey"
  fi
  run_as_target "$TARGET_HOME/myvenv/bin/python" -m pip \
    install -r "$TARGET_HOME/Portsey/requirements.txt"
}

# ---------------------------------------------------------------------------
# scopatz/nanorc. Repo lives directly at ~/.nano; user's .nanorc is installed
# later. sudo nano reads the same config via /root/.nanorc symlink.
# ---------------------------------------------------------------------------

verify_nanorc_repo() {
  [[ -d "$TARGET_HOME/.nano/.git" ]] &&
  find "$TARGET_HOME/.nano" -maxdepth 1 -name '*.nanorc' -type f -print -quit | grep -q . &&
  [[ -L /root/.nanorc ]] &&
  [[ "$(readlink -f /root/.nanorc)" == "$TARGET_HOME/.nanorc" ]]
}

setup_nanorc_repo() {
  if [[ -d "$TARGET_HOME/.nano/.git" ]]; then
    run_as_target git -C "$TARGET_HOME/.nano" fetch --all --prune
    run_as_target git -C "$TARGET_HOME/.nano" pull --ff-only
  else
    rm -rf "$TARGET_HOME/.nano"
    run_as_target git clone "$NANORC_REPO" "$TARGET_HOME/.nano"
  fi
  chown -R "$TARGET_USER:$TARGET_USER" "$TARGET_HOME/.nano"

  # The attached nanorc uses an absolute /home/jq/.nano/*.nanorc include, so
  # root only needs the config-file symlink; both `nano` and `sudo nano` share it.
  ln -sfn "$TARGET_HOME/.nanorc" /root/.nanorc
}

