# ---------------------------------------------------------------------------
# Curated terminal theme pairs.
#
# Randomness chooses only among complete, hand-designed pairs. It never mixes
# individual colors/separators from different themes. Every pair keeps the
# same information architecture: two prompt lines with OS icon, current path,
# Python environment, hostname (without username), Tailscale IPv4 and time.
# ---------------------------------------------------------------------------

terminal_theme_supported() {
  case "${1:-}" in
    neon-katana|solar-flare|arctic-circuit|acid-rain|violet-reactor|emberline|deep-ocean|mono-signal) return 0 ;;
    *) return 1 ;;
  esac
}

write_terminal_theme_pair() {
  local theme="$1"
  local name os_fg os_bg dir_fg dir_bg py_fg py_bg vcs_fg vcs_bg host_fg host_bg ts_fg ts_bg time_fg time_bg
  local status_fg status_bg duration_fg duration_bg line_fg gap_fg left_sep right_sep left_sub right_sub gap_char prompt_char
  local first_prefix last_prefix first_suffix last_suffix
  local nano_title nano_status nano_error nano_selected nano_stripe nano_number nano_key nano_function nano_prompt nano_spot nano_scroll

  case "$theme" in
    neon-katana)
      name='Neon Katana'
      os_fg=231; os_bg=54; dir_fg=16; dir_bg=45; py_fg=16; py_bg=81; vcs_fg=16; vcs_bg=213
      host_fg=231; host_bg=91; ts_fg=16; ts_bg=50; time_fg=16; time_bg=227
