      left_sep=''; right_sep=''; left_sub=''; right_sub=''; gap_char='·'; prompt_char='❯'
      first_prefix='%F{213}╭─%f'; last_prefix='%F{45}╰─%f'; first_suffix='%F{54}─╮%f'; last_suffix='%F{91}─╯%f'
      nano_title='bold,brightcyan,black'; nano_status='bold,brightmagenta,black'; nano_error='bold,brightred,black'
      nano_selected='black,cyan'; nano_stripe='brightmagenta,black'; nano_number='brightcyan,black'; nano_key='brightyellow,black'
      nano_function='brightmagenta,black'; nano_prompt='bold,brightcyan,black'; nano_spot='black,yellow'; nano_scroll='brightcyan,black'
      ;;
    solar-flare)
      name='Solar Flare'
      os_fg=232; os_bg=220; dir_fg=232; dir_bg=214; py_fg=231; py_bg=202; vcs_fg=231; vcs_bg=196
      host_fg=232; host_bg=221; ts_fg=232; ts_bg=208; time_fg=231; time_bg=160
      status_fg=231; status_bg=88; duration_fg=232; duration_bg=215; line_fg=214; gap_fg=130
      left_sep=''; right_sep=''; left_sub='╱'; right_sub='╲'; gap_char='─'; prompt_char='➜'
      first_prefix='%F{220}╭━%f'; last_prefix='%F{202}╰╴%f'; first_suffix='%F{196}━╮%f'; last_suffix='%F{208}╴╯%f'
      nano_title='bold,brightyellow,red'; nano_status='bold,brightred,black'; nano_error='bold,brightwhite,red'
      nano_selected='black,yellow'; nano_stripe='brightyellow,black'; nano_number='brightred,black'; nano_key='brightyellow,black'
      nano_function='brightred,black'; nano_prompt='bold,brightyellow,black'; nano_spot='black,yellow'; nano_scroll='brightred,black'
      ;;
    arctic-circuit)
      name='Arctic Circuit'
      os_fg=16; os_bg=159; dir_fg=16; dir_bg=117; py_fg=16; py_bg=81; vcs_fg=231; vcs_bg=33
      host_fg=16; host_bg=153; ts_fg=16; ts_bg=87; time_fg=231; time_bg=27
      status_fg=231; status_bg=24; duration_fg=16; duration_bg=152; line_fg=117; gap_fg=67
      left_sep=''; right_sep=''; left_sub='•'; right_sub='•'; gap_char='·'; prompt_char='❄'
      first_prefix='%F{117}╭─%f'; last_prefix='%F{81}╰─%f'; first_suffix='%F{33}─╮%f'; last_suffix='%F{87}─╯%f'
      nano_title='bold,brightwhite,blue'; nano_status='bold,brightcyan,black'; nano_error='bold,brightred,black'
      nano_selected='black,cyan'; nano_stripe='brightblue,black'; nano_number='brightcyan,black'; nano_key='brightwhite,blue'
