      first_prefix='%F{135}╭╴%f'; last_prefix='%F{99}╰╴%f'; first_suffix='%F{164}╴╮%f'; last_suffix='%F{126}╴╯%f'
      nano_title='bold,brightmagenta,black'; nano_status='bold,brightcyan,magenta'; nano_error='bold,brightred,black'
      nano_selected='black,magenta'; nano_stripe='brightmagenta,black'; nano_number='brightmagenta,black'; nano_key='brightcyan,black'
