      host_fg=231; host_bg=94; ts_fg=231; ts_bg=130; time_fg=232; time_bg=220
      status_fg=231; status_bg=160; duration_fg=232; duration_bg=214; line_fg=202; gap_fg=95
      left_sep=''; right_sep=''; left_sub='⋮'; right_sub='⋮'; gap_char='━'; prompt_char='›'
      first_prefix='%F{202}╓─%f'; last_prefix='%F{166}╙─%f'; first_suffix='%F{208}─╖%f'; last_suffix='%F{220}─╜%f'
      nano_title='bold,brightyellow,black'; nano_status='bold,brightred,black'; nano_error='bold,brightwhite,red'
      nano_selected='white,red'; nano_stripe='brightred,black'; nano_number='brightyellow,black'; nano_key='brightyellow,red'
