    deep-ocean)
      name='Deep Ocean'
      os_fg=231; os_bg=17; dir_fg=231; dir_bg=18; py_fg=231; py_bg=24; vcs_fg=16; vcs_bg=37
      host_fg=231; host_bg=19; ts_fg=16; ts_bg=44; time_fg=16; time_bg=80
