      left_sep=''; right_sep=''; left_sub='≈'; right_sub='≈'; gap_char='─'; prompt_char='❱'
      first_prefix='%F{44}╭≈%f'; last_prefix='%F{37}╰≈%f'; first_suffix='%F{24}≈╮%f'; last_suffix='%F{80}≈╯%f'
      nano_title='bold,brightcyan,blue'; nano_status='bold,brightwhite,blue'; nano_error='bold,brightred,black'
