    mono-signal)
      name='Mono Signal'
      os_fg=232; os_bg=252; dir_fg=231; dir_bg=240; py_fg=232; py_bg=250; vcs_fg=231; vcs_bg=244
      host_fg=232; host_bg=255; ts_fg=231; ts_bg=238; time_fg=232; time_bg=248
      status_fg=231; status_bg=236; duration_fg=232; duration_bg=250; line_fg=250; gap_fg=242
      left_sep=''; right_sep=''; left_sub='│'; right_sub='│'; gap_char='·'; prompt_char='▶'
      first_prefix='%F{250}┏━%f'; last_prefix='%F{250}┗━%f'; first_suffix='%F{250}━┓%f'; last_suffix='%F{250}━┛%f'
      nano_title='bold,brightwhite,black'; nano_status='black,white'; nano_error='bold,brightred,black'
      nano_selected='black,white'; nano_stripe='brightwhite,black'; nano_number='brightwhite,black'; nano_key='brightcyan,black'
