  local theme_dir="$TARGET_HOME/.config/jq-theme"
  install -d -m 0755 -o "$TARGET_USER" -g "$TARGET_USER" "$theme_dir"

  cat > "$theme_dir/p10k.zsh" <<EOF_JQ_P10K_THEME
# jq bootstrap curated Powerlevel10k overlay: $name ($theme)
typeset -g JQ_THEME_ID='$theme'
typeset -g JQ_THEME_NAME='$name'
typeset -g JQ_THEME_PY_FG=$py_fg
typeset -g JQ_THEME_PY_BG=$py_bg
typeset -g JQ_THEME_HOST_FG=$host_fg
typeset -g JQ_THEME_HOST_BG=$host_bg
typeset -g JQ_THEME_TS_FG=$ts_fg
typeset -g JQ_THEME_TS_BG=$ts_bg
EOF_JQ_P10K_THEME

  cat >> "$theme_dir/p10k.zsh" <<'EOF_JQ_P10K_THEME_STATIC'
# These custom segments deliberately expose only the requested information.
function prompt_python_env() {
  local env_name=''
  if [[ -n ${VIRTUAL_ENV-} ]]; then
    env_name=${VIRTUAL_ENV:t}
  elif [[ -n ${CONDA_DEFAULT_ENV-} ]]; then
    env_name=$CONDA_DEFAULT_ENV
  elif [[ -n ${PYENV_VERSION-} ]]; then
    env_name=$PYENV_VERSION
  fi
  [[ -n $env_name ]] || return
  p10k segment -f "$JQ_THEME_PY_FG" -b "$JQ_THEME_PY_BG" -i '' -t "$env_name"
}

function prompt_jq_host() {
  p10k segment -f "$JQ_THEME_HOST_FG" -b "$JQ_THEME_HOST_BG" -i '󰒋' -t '%m'
}

function prompt_tailscale_ip() {
  (( $+commands[tailscale] )) || return
  local -a _jq_ts_ips
  _jq_ts_ips=("${(@f)$(command tailscale ip -4 2>/dev/null)}")
  [[ -n ${_jq_ts_ips[1]-} ]] || return
  p10k segment -f "$JQ_THEME_TS_FG" -b "$JQ_THEME_TS_BG" -i '󰖂' -t "${_jq_ts_ips[1]}"
}

# Exactly two prompt lines. The information layout never changes between themes.
typeset -g POWERLEVEL9K_LEFT_PROMPT_ELEMENTS=(os_icon dir python_env vcs newline prompt_char)
typeset -g POWERLEVEL9K_RIGHT_PROMPT_ELEMENTS=(jq_host tailscale_ip time newline status command_execution_time)
typeset -g POWERLEVEL9K_MODE=nerdfont-v3
typeset -g POWERLEVEL9K_ICON_PADDING=none
typeset -g POWERLEVEL9K_PROMPT_ADD_NEWLINE=true
typeset -g POWERLEVEL9K_TRANSIENT_PROMPT=same-dir
typeset -g POWERLEVEL9K_DISABLE_HOT_RELOAD=true
EOF_JQ_P10K_THEME_STATIC

  cat >> "$theme_dir/p10k.zsh" <<EOF_JQ_P10K_THEME_STYLE
# Curated geometry and palette for $name.
typeset -g POWERLEVEL9K_BACKGROUND=
typeset -g POWERLEVEL9K_LEFT_SEGMENT_SEPARATOR='$left_sep'
typeset -g POWERLEVEL9K_RIGHT_SEGMENT_SEPARATOR='$right_sep'
typeset -g POWERLEVEL9K_LEFT_SUBSEGMENT_SEPARATOR='$left_sub'
typeset -g POWERLEVEL9K_RIGHT_SUBSEGMENT_SEPARATOR='$right_sub'
typeset -g POWERLEVEL9K_LEFT_PROMPT_FIRST_SEGMENT_START_SYMBOL=''
typeset -g POWERLEVEL9K_RIGHT_PROMPT_LAST_SEGMENT_END_SYMBOL=''
typeset -g POWERLEVEL9K_MULTILINE_FIRST_PROMPT_PREFIX='$first_prefix'
typeset -g POWERLEVEL9K_MULTILINE_NEWLINE_PROMPT_PREFIX='%F{$line_fg}├─%f'
typeset -g POWERLEVEL9K_MULTILINE_LAST_PROMPT_PREFIX='$last_prefix'
typeset -g POWERLEVEL9K_MULTILINE_FIRST_PROMPT_SUFFIX='$first_suffix'
typeset -g POWERLEVEL9K_MULTILINE_NEWLINE_PROMPT_SUFFIX='%F{$line_fg}─┤%f'
typeset -g POWERLEVEL9K_MULTILINE_LAST_PROMPT_SUFFIX='$last_suffix'
typeset -g POWERLEVEL9K_MULTILINE_FIRST_PROMPT_GAP_CHAR='$gap_char'
typeset -g POWERLEVEL9K_MULTILINE_FIRST_PROMPT_GAP_FOREGROUND=$gap_fg
typeset -g POWERLEVEL9K_OS_ICON_FOREGROUND=$os_fg
typeset -g POWERLEVEL9K_OS_ICON_BACKGROUND=$os_bg
typeset -g POWERLEVEL9K_DIR_FOREGROUND=$dir_fg
typeset -g POWERLEVEL9K_DIR_BACKGROUND=$dir_bg
typeset -g POWERLEVEL9K_VCS_CLEAN_FOREGROUND=$vcs_fg
typeset -g POWERLEVEL9K_VCS_CLEAN_BACKGROUND=$vcs_bg
typeset -g POWERLEVEL9K_VCS_MODIFIED_FOREGROUND=$vcs_fg
typeset -g POWERLEVEL9K_VCS_MODIFIED_BACKGROUND=$vcs_bg
typeset -g POWERLEVEL9K_VCS_UNTRACKED_FOREGROUND=$vcs_fg
typeset -g POWERLEVEL9K_VCS_UNTRACKED_BACKGROUND=$vcs_bg
typeset -g POWERLEVEL9K_TIME_FOREGROUND=$time_fg
typeset -g POWERLEVEL9K_TIME_BACKGROUND=$time_bg
typeset -g POWERLEVEL9K_TIME_FORMAT='%D{%H:%M:%S}'
typeset -g POWERLEVEL9K_STATUS_OK_FOREGROUND=$status_fg
typeset -g POWERLEVEL9K_STATUS_OK_BACKGROUND=$status_bg
typeset -g POWERLEVEL9K_STATUS_ERROR_FOREGROUND=231
typeset -g POWERLEVEL9K_STATUS_ERROR_BACKGROUND=196
typeset -g POWERLEVEL9K_COMMAND_EXECUTION_TIME_FOREGROUND=$duration_fg
typeset -g POWERLEVEL9K_COMMAND_EXECUTION_TIME_BACKGROUND=$duration_bg
typeset -g POWERLEVEL9K_COMMAND_EXECUTION_TIME_THRESHOLD=2
typeset -g POWERLEVEL9K_PROMPT_CHAR_BACKGROUND=
typeset -g POWERLEVEL9K_PROMPT_CHAR_OK_{VIINS,VICMD,VIVIS,VIOWR}_FOREGROUND=$line_fg
typeset -g POWERLEVEL9K_PROMPT_CHAR_ERROR_{VIINS,VICMD,VIVIS,VIOWR}_FOREGROUND=196
typeset -g POWERLEVEL9K_PROMPT_CHAR_{OK,ERROR}_VIINS_CONTENT_EXPANSION='$prompt_char'
typeset -g POWERLEVEL9K_PROMPT_CHAR_{OK,ERROR}_VICMD_CONTENT_EXPANSION='❮'
typeset -g POWERLEVEL9K_PROMPT_CHAR_{OK,ERROR}_VIVIS_CONTENT_EXPANSION='◆'
typeset -g POWERLEVEL9K_PROMPT_CHAR_{OK,ERROR}_VIOWR_CONTENT_EXPANSION='▶'
typeset -g POWERLEVEL9K_PROMPT_CHAR_LEFT_{LEFT,RIGHT}_WHITESPACE=
typeset -g POWERLEVEL9K_PROMPT_CHAR_LEFT_PROMPT_LAST_SEGMENT_END_SYMBOL=
EOF_JQ_P10K_THEME_STYLE

  cat > "$theme_dir/nanorc" <<EOF_JQ_NANO_THEME
# jq bootstrap curated GNU nano UI theme: $name ($theme)
set titlecolor $nano_title
set statuscolor $nano_status
set errorcolor $nano_error
set selectedcolor $nano_selected
set stripecolor $nano_stripe
set numbercolor $nano_number
set keycolor $nano_key
set functioncolor $nano_function
set promptcolor $nano_prompt
set spotlightcolor $nano_spot
set scrollercolor $nano_scroll
EOF_JQ_NANO_THEME

  printf '%s\n%s\n' "$theme" "$name" > "$theme_dir/selection"
  chown "$TARGET_USER:$TARGET_USER" "$theme_dir/p10k.zsh" "$theme_dir/nanorc" "$theme_dir/selection"
  chmod 0644 "$theme_dir/p10k.zsh" "$theme_dir/nanorc" "$theme_dir/selection"
  printf '%s\n' "$theme" > "$STATE_DIR/terminal-theme-id"
  chmod 0600 "$STATE_DIR/terminal-theme-id"

  # Validate the common Zsh overlay immediately; all themes use the same logic,
  # only the curated palette/geometry constants differ.
  run_as_target /usr/bin/zsh -n "$theme_dir/p10k.zsh"
  TERMINAL_THEME_SELECTED="$theme"
  TERMINAL_THEME_SELECTED_NAME="$name"
  ok "Terminal theme pair selected: $name ($theme)"
}

select_random_terminal_theme() {
  local theme="${TERMINAL_THEME:-random}"
  local -a themes=(neon-katana solar-flare arctic-circuit acid-rain violet-reactor emberline deep-ocean mono-signal)
  if [[ -z "$theme" || "$theme" == 'random' || "$theme" == 'auto' ]]; then
    if command -v shuf >/dev/null 2>&1; then
      theme="$(printf '%s\n' "${themes[@]}" | shuf -n 1)"
    else
      theme="${themes[$((RANDOM % ${#themes[@]}))]}"
    fi
  fi
  terminal_theme_supported "$theme" || die "TERMINAL_THEME must be random/auto or one of: ${themes[*]}"
  write_terminal_theme_pair "$theme"
}

verify_terminal_theme() {
  local d="$TARGET_HOME/.config/jq-theme" id
  [[ -s "$d/selection" && -s "$d/p10k.zsh" && -s "$d/nanorc" ]] || return 1
  id="$(sed -n '1p' "$d/selection" 2>/dev/null)"
  terminal_theme_supported "$id" || return 1
  /usr/bin/zsh -n "$d/p10k.zsh" >/dev/null 2>&1 || return 1
  grep -Fq 'POWERLEVEL9K_LEFT_PROMPT_ELEMENTS=(os_icon dir python_env vcs newline prompt_char)' "$d/p10k.zsh" || return 1
  grep -Fq 'POWERLEVEL9K_RIGHT_PROMPT_ELEMENTS=(jq_host tailscale_ip time newline status command_execution_time)' "$d/p10k.zsh" || return 1
  grep -Fq 'set titlecolor ' "$d/nanorc" || return 1
  grep -Fq 'set promptcolor ' "$d/nanorc" || return 1
  # GNU nano rejects global `set` directives in included syntax files.
  # Verify that the generated palette was embedded in the top-level nanorc.
  cmp -s "$d/nanorc" <(sed -n '/^# jq bootstrap curated GNU nano UI theme:/,$p' "$TARGET_HOME/.nanorc") || return 1
  ! grep -Fq 'include "/home/jq/.config/jq-theme/nanorc"' "$TARGET_HOME/.nanorc"
}

write_embedded_dotfiles() {
  cat > "$TARGET_HOME/.zshenv" <<'__JQ_ZSHENV_EOF__'
# Documentation: https://github.com/romkatv/zsh4humans/blob/v5/README.md.
#
# Do not modify this file unless you know exactly what you are doing.
# It is strongly recommended to keep all shell customization and configuration
# (including exported environment variables such as PATH) in ~/.zshrc or in
# files sourced from ~/.zshrc. If you are certain that you must export some
# environment variables in ~/.zshenv, do it where indicated by comments below.

if [ -n "${ZSH_VERSION-}" ]; then
  # If you are certain that you must export some environment variables
  # in ~/.zshenv (see comments at the top!), do it here:
  #
  #   export GOPATH=$HOME/go
  #
  # Do not change anything else in this file.

  : ${ZDOTDIR:=~}
  setopt no_global_rcs
  [[ -o no_interactive && -z "${Z4H_BOOTSTRAPPING-}" ]] && return
  setopt no_rcs
  unset Z4H_BOOTSTRAPPING
fi

Z4H_URL="https://raw.githubusercontent.com/romkatv/zsh4humans/v5"
: "${Z4H:=${XDG_CACHE_HOME:-$HOME/.cache}/zsh4humans/v5}"

umask o-w

if [ ! -e "$Z4H"/z4h.zsh ]; then
  mkdir -p -- "$Z4H" || return
  >&2 printf '\033[33mz4h\033[0m: fetching \033[4mz4h.zsh\033[0m\n'
  if command -v curl >/dev/null 2>&1; then
    curl -fsSL -- "$Z4H_URL"/z4h.zsh >"$Z4H"/z4h.zsh.$$ || return
  elif command -v wget >/dev/null 2>&1; then
    wget -O-   -- "$Z4H_URL"/z4h.zsh >"$Z4H"/z4h.zsh.$$ || return
  else
    >&2 printf '\033[33mz4h\033[0m: please install \033[32mcurl\033[0m or \033[32mwget\033[0m\n'
    return 1
  fi
  mv -- "$Z4H"/z4h.zsh.$$ "$Z4H"/z4h.zsh || return
fi

. "$Z4H"/z4h.zsh || return

setopt rcs
