# oproxy: manage the private-api-proxy key rotator + Tailscale funnel
oproxy() {
  local proxy_dir="/home/jq/private-api-proxy-key-rotator"
  local proxy_port=2025
  local pidfile="/tmp/oproxy_pids"
  case "$1" in
    up)
      # Stop anything already on the port / funnel so we start clean
      oproxy down >/dev/null 2>&1
      # Start the proxy
      cd "$proxy_dir" || { echo "Cannot cd to $proxy_dir"; return 1; }
      pnpm start > /tmp/oproxy_proxy.log 2>&1 &
      echo $! > "$pidfile"
      # Wait for the proxy to actually listen on $proxy_port
      local i
      for i in $(seq 1 30); do
        if ss -ltn 2>/dev/null | grep -q ":$proxy_port "; then
          break
        fi
        sleep 0.5
      done
      if ! ss -ltn 2>/dev/null | grep -q ":$proxy_port "; then
        echo "WARNING: proxy did not come up on port $proxy_port. Log:"
        tail -n 20 /tmp/oproxy_proxy.log 2>/dev/null
        return 1
      fi
      # Start the funnel in the background (managed by tailscale)
      if tailscale funnel --bg "http://127.0.0.1:$proxy_port" 2>/tmp/oproxy_funnel.log; then
        echo "oproxy up: proxy listening on :$proxy_port, funnel started"
      else
        echo "oproxy up: proxy is up but funnel failed to start. Log:"
        cat /tmp/oproxy_funnel.log 2>/dev/null
      fi
      ;;
    down)
      # Stop the tailscale funnel
      if tailscale funnel reset >/dev/null 2>&1; then
        echo "funnel stopped"
      else
        echo "no funnel running"
      fi
      # Kill the proxy process (pnpm + its node child) via the port
      if fuser -k "${proxy_port}/tcp" >/dev/null 2>&1; then
        echo "killed process on port $proxy_port"
      fi
      # Also kill saved pnpm pid if still alive
      if [ -f "$pidfile" ]; then
        while read -r pid; do
          [ -n "$pid" ] && kill "$pid" 2>/dev/null
        done < "$pidfile"
        rm -f "$pidfile"
      fi
      ;;
    status)
      echo "== Tailscale funnel =="
      tailscale funnel status 2>/dev/null || echo "funnel: not running"
      echo
      echo "== Proxy (port $proxy_port) =="
      if ss -ltn 2>/dev/null | grep -q ":$proxy_port "; then
        echo "LISTENING on :$proxy_port"
        ss -ltnp 2>/dev/null | grep ":$proxy_port "
      else
        echo "NOT listening on :$proxy_port"
      fi
      ;;
    *)
      echo "Usage: oproxy up|down|status"
      ;;
  esac
}

# ═══════════════════════════════════════════════════════════════════════════════
# OCI VM Restart Functions (with progress bar)
# ═══════════════════════════════════════════════════════════════════════════════

_oci_reboot() {
  local name="$1" instance_id="$2" region="$3" profile="$4"
  local bar_width=40

  echo "🔄 Rebooting $name ..."

  local result
  result=$(oci compute instance action \
    --instance-id "$instance_id" \
    --action RESET \
    --region "$region" \
    --profile "$profile" \
    2>&1)

  if echo "$result" | grep -q '"code"'; then
    echo "❌ Failed to send reboot command:"
    echo "$result" | grep '"message"'
    return 1
  fi

  echo "⏳ Waiting for $name to come back RUNNING..."

  # State → progress % mapping
  _state_pct() {
    case "$1" in
      RUNNING)       echo 5  ;;   # initial running before stop
      STOPPING)      echo 25 ;;
      STOPPED)       echo 50 ;;
      STARTING)      echo 75 ;;
      *)             echo 10 ;;
    esac
  }

  local elapsed=0
  local timeout=300
  local state=""
  local seen_stopping=0

  while [[ $elapsed -lt $timeout ]]; do
    state=$(oci compute instance get \
      --instance-id "$instance_id" \
      --region "$region" \
      --profile "$profile" \
      --query 'data."lifecycle-state"' \
      --raw-output 2>/dev/null)

    [[ "$state" == "STOPPING" || "$state" == "STOPPED" ]] && seen_stopping=1

    local pct
    if [[ "$state" == "RUNNING" && $seen_stopping -eq 1 ]]; then
      pct=100
    else
      pct=$(_state_pct "$state")
    fi

    local filled=$(( bar_width * pct / 100 ))
    local empty=$(( bar_width - filled ))
    local bar="["
    for ((i=0; i<filled; i++)); do bar+="█"; done
    for ((i=0; i<empty; i++)); do bar+="░"; done
    bar+="] ${pct}% — ${state:-checking...}"
    printf "\r%-80s" "$bar"

    if [[ "$state" == "RUNNING" && $seen_stopping -eq 1 ]]; then
      printf "\r%-80s\n" ""
      echo "✅ $name is back RUNNING! (${elapsed}s)"
      return 0
    fi

    sleep 1
    elapsed=$(( elapsed + 1 ))
  done

  printf "\r%-80s\n" ""
  echo "⚠️  Timed out waiting for $name. Last state: $state"
  return 1
}

