JQ_BRAND_FAV_B64

  local font
  font="$(fc-match -f '%{file}\n' 'DejaVu Sans Condensed:style=Bold Oblique' | head -n1)"
  [[ -s "$font" ]] || die "Could not resolve the embedded branding font."

  python3 - "$tmp/master_blank_4k.jpg" "$tmp/login.jpg" "$font" "$title" "$AAPANEL_BRANDING_SUBTITLE" <<'PY_RENDER_BRAND'
from PIL import Image,ImageDraw,ImageFont,ImageFilter
import sys
src,out,font_path,title,subtitle=sys.argv[1:]
im=Image.open(src).convert("RGBA")
layer=Image.new("RGBA",(1400,260),(0,0,0,0))
def fit(text,maxw,start=78,minsize=40):
    for size in range(start,minsize-1,-2):
        f=ImageFont.truetype(font_path,size)
        bb=f.getbbox(text,stroke_width=1)
        if bb[2]-bb[0] <= maxw:
            return f
    return ImageFont.truetype(font_path,minsize)
f=fit(title,1090)
sf=ImageFont.truetype(font_path,34)
glow=Image.new("RGBA",layer.size,(0,0,0,0))
gd=ImageDraw.Draw(glow)
gd.text((24,34),title,font=f,fill=(74,255,48,180),stroke_width=3,stroke_fill=(17,85,16,120))
glow=glow.filter(ImageFilter.GaussianBlur(8))
layer=Image.alpha_composite(layer,glow)
ld=ImageDraw.Draw(layer)
ld.text((24,34),title,font=f,fill=(105,225,72,255),stroke_width=2,stroke_fill=(0,0,0,255))
ld.text((28,132),subtitle,font=sf,fill=(174,190,174,230))
layer=layer.rotate(-3.0,resample=Image.Resampling.BICUBIC,expand=True)
im.alpha_composite(layer,(585,287))
im.convert("RGB").save(out,"JPEG",quality=92,subsampling=0,optimize=True)
PY_RENDER_BRAND

  install -m 0644 "$tmp/login.jpg" "$static/jq_login_bg.jpg"
  install -m 0644 "$tmp/menu_logo.png" "$static/jq_menu_logo.png"
  install -m 0644 "$tmp/favicon.png" "$static/jq_favicon.png"

  python3 - "$AAPANEL_PANEL_DIR/data/panel_asset.json" <<'PY_PANEL_ASSET'
import json,sys,os
p=sys.argv[1]
d=json.load(open(p)) if os.path.exists(p) else {}
d.setdefault("logo",{})["image"]="/static/temp/jq_menu_logo.png"
d["logo"]["favicon"]="/static/temp/jq_favicon.png"
login=d.setdefault("login",{})
login["is_show_bg"]="true"
login["bg_image"]="/static/temp/jq_login_bg.jpg"
login["bg_image_opacity"]=100
login.setdefault("content_opacity",100)
with open(p,"w") as f:
    json.dump(d,f,ensure_ascii=False,indent=4)
    f.write("\n")
PY_PANEL_ASSET
  chmod 0644 "$AAPANEL_PANEL_DIR/data/panel_asset.json"

  /etc/init.d/bt reload >/dev/null 2>&1 || /etc/init.d/bt restart >/dev/null 2>&1 || true
  local i
  for i in $(seq 1 30); do
    verify_aapanel_branding && break
    sleep 1
  done
  verify_aapanel_branding || die "aaPanel branding verification failed."
}

main "$@"
